import type { DeepPartial, Theme } from "@types";

export const getBrowserFontSize = () => {
  if (typeof window === "undefined") {
    return 16;
  }
  return parseFloat(getComputedStyle(document.documentElement).fontSize);
};

const getBaseThemeFontSize = (theme: DeepPartial<Theme>) => {
  if (theme.cssVariables) {
    const cssValue = getCssVariableValue("--ntx-typography-body-md-font-size", theme);
    if (cssValue) {
      return cssValue;
    }
  }
  return theme.typography?.body?.md?.fontSize;
};

const getCssVariableValue = (variableName: string, theme: DeepPartial<Theme>): string | null => {
  if (theme.cssVariables) {
    const regex = new RegExp(`${variableName}\\s*:\\s*([^;]+)`);
    const match = theme.cssVariables.match(regex);
    if (match?.[1]) {
      return match[1].trim();
    }
  }
  return null;
};

const getValueAndUnit = (value: string) => {
  const unit = value.match(/px|rem|em|%/);
  const num = value.match(/-?\d+(\.\d+)?/);
  return {
    value: num ? parseFloat(num[0]) : null,
    unit: unit ? unit[0] : null,
  };
};

const resolveCssVariable = (value: string, theme: DeepPartial<Theme>) => {
  if (value.startsWith("var(")) {
    const variableNameMatch = value.match(/var\((--[^)]+)\)/);
    if (variableNameMatch) {
      const variableName = variableNameMatch[1];
      return getCssVariableValue(variableName, theme);
    }
  }
  return value;
};

const CssSizeUnitConverter = (theme: DeepPartial<Theme>) => {
  const baseFontSize = getBaseThemeFontSize(theme);
  const browserBaseFontSize = getBrowserFontSize();
  let basePx = browserBaseFontSize;

  if (baseFontSize) {
    const { value: baseValue, unit: baseUnit } = getValueAndUnit(baseFontSize);
    if (baseValue) {
      if (baseUnit === "rem" || baseUnit === "em") {
        basePx = baseValue * browserBaseFontSize;
      } else {
        basePx = baseValue;
      }
    }
  }

  return {
    toRem: (value: number | string) => {
      let px = 0;
      if (typeof value === "string") {
        const resolvedValue = resolveCssVariable(value, theme);
        if (resolvedValue) {
          const { value: val, unit } = getValueAndUnit(resolvedValue);
          if (val) {
            if (unit === "rem" || unit === "em") {
              px = val * browserBaseFontSize;
            } else {
              px = val;
            }
          }
        }
      } else {
        px = value;
      }
      return `${px / basePx}rem`;
    },
    toPx: (value: number | string) => {
      let rem = 0;
      if (typeof value === "string") {
        const resolvedValue = resolveCssVariable(value, theme);
        if (resolvedValue) {
          const { value: val, unit } = getValueAndUnit(resolvedValue);
          if (val) {
            if (unit === "px") {
              return val;
            }
            rem = val;
          }
        }
      } else {
        rem = value;
      }

      return Math.round(rem * basePx);
    },
    resolveFontSize: (fontSize: string) => {
      const resolvedValue = resolveCssVariable(fontSize, theme);
      if (resolvedValue) {
        const { value: val, unit } = getValueAndUnit(resolvedValue);
        if (val) {
          if (unit === "rem" || unit === "em") {
            return val * browserBaseFontSize;
          }
          return val;
        }
      }
    },
  };
};

export const boxShadowToDropShadow = (boxShadow: string, theme: DeepPartial<Theme>): string => {
  if (!boxShadow || boxShadow === "none") {
    return "none";
  }
  const resolvedBoxShadow = resolveCssVariable(boxShadow, theme);
  if (!resolvedBoxShadow) {
    return "none";
  }

  const shadowStrings = resolvedBoxShadow.split(/,(?![^()]*\))/);
  const dropShadows = shadowStrings.map((shadow) => {
    const shadowString = shadow.trim();
    const colorRegex = /(rgba?\(.*\)|#\w{3,6}|[a-z]+)$/;
    const colorMatch = shadowString.match(colorRegex);
    let color = "";
    let valuesString = shadowString;

    if (colorMatch) {
      color = colorMatch[0];
      valuesString = shadowString.replace(color, "").trim();
    }

    const values = valuesString.split(" ");
    const [offsetX, offsetY, blurRadius] = values;

    return `drop-shadow(${offsetX} ${offsetY} ${blurRadius} ${color})`.trim();
  });

  return dropShadows.join(" ");
};

export { CssSizeUnitConverter };
